  Lemma skip_zeros_ok f g j :
    0 <= j <= aS -> aS - j < Z.of_nat f -> maxSV - j < Z.of_nat g ->
    skip_zeros nc aS f j = Ok (next_nz nc maxSV g j).
Proof.
