  Definition same_ctl (s s' : wstate) : Prop :=
    w_symbol s' = w_symbol s /\ w_remaining s' = w_remaining s /\ w_threshold s' = w_threshold s /\
    w_nbBits s' = w_nbBits s /\ w_previousIs0 s' = w_previousIs0 s.

